// n8n · F12 · nodo "Trabajos TRM" (Code, una vez para todos los elementos).
// TRM oficial de datos.gov.co (no pide clave). A las 7 a. m. carga los últimos 10 días; a mano, desde 2024.
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const hora = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Bogota', hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
const manual = !$input.first().json.timestamp;
if (!manual && hora !== 7) return [];

const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const desde = manual ? '2024-01-01' : sumar(hoy, -10);
const donde = encodeURIComponent(`vigenciahasta >= '${desde}T00:00:00'`);
return [{ json: { fuente: 'trm', tabla: 'trm_diaria', desde, hasta: hoy, sitio: null,
  url: `https://www.datos.gov.co/resource/32sa-8pi3.json?$order=vigenciadesde&$limit=5000&$where=${donde}` } }];

// n8n · F12 · nodo "Filas TRM" (Code, una vez para todos los elementos).
// datos.gov.co devuelve tramos de vigencia (un fin de semana es un solo tramo); aquí se abren en un valor por día.
const t = $('Trabajos TRM').first().json;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };

const porDia = new Map();
for (const { json: x } of $input.all()) {
  if (!x || !x.vigenciadesde) continue;
  const valor = Number(x.valor);
  for (let d = x.vigenciadesde.slice(0, 10); d <= x.vigenciahasta.slice(0, 10); d = sumar(d, 1)) {
    if (d >= t.desde && d <= t.hasta) porDia.set(d, valor);
  }
}
const filas = [...porDia].map(([fecha, valor]) => ({ fecha, valor }));
const fechas = filas.map((f) => f.fecha).sort();
if (!filas.length) return [];
return [{ json: { p_tabla: 'trm_diaria', p_desde: fechas[0], p_hasta: fechas[fechas.length - 1], p_filas: filas, p_fuente: 'trm', p_sitio: null } }];

// n8n · F12 · nodo "Trabajos Brevo" (Code, una vez para todos los elementos).
// Cada hora: correos de las automatizaciones de los últimos 3 días y todas las campañas masivas enviadas.
// Corrido a mano: correos de los últimos 90 días, por tramos de 5 días.
// Los eventos se piden con un día de margen a cada lado (Brevo no usa la hora de Bogotá) y luego se recortan.
const BASE = 'https://api.brevo.com/v3';
const LIMITE = 2500; // si un tramo llega a este número, "Filas Brevo" avisa con un error para partirlo más

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const manual = !$input.first().json.timestamp;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const tramos = (desde, hasta, dias) => {
  const out = [];
  for (let a = desde; a <= hasta; a = sumar(a, dias)) { const b = sumar(a, dias - 1); out.push([a, b < hasta ? b : hasta]); }
  return out;
};

const eventos = (manual ? tramos(sumar(hoy, -89), hoy, 5) : [[sumar(hoy, -2), hoy]]).map(([desde, hasta]) => ({ json: {
  fuente: 'brevo', tabla: 'brevo_evento_diario', desde, hasta, sitio: null, limite: LIMITE,
  url: `${BASE}/smtp/statistics/events?limit=${LIMITE}&offset=0&sort=desc&startDate=${sumar(desde, -1)}&endDate=${sumar(hasta, 1) > hoy ? hoy : sumar(hasta, 1)}`,
} }));

const campanas = { json: {
  fuente: 'brevo', tabla: 'brevo_campana', desde: '2000-01-01', hasta: '2100-12-31', sitio: null,
  url: `${BASE}/emailCampaigns?type=classic&status=sent&statistics=globalStats&excludeHtmlContent=true&limit=100&offset=0`,
} };

return [...eventos, campanas];

// n8n · F12 · nodos "Filas Google", "Filas Meta" y "Filas Brevo" (Code, una vez por elemento).
// Convierte la respuesta de cada API en filas de la tabla de Supabase y arma la llamada a cargar().
const t = $('Trabajos Brevo').item.json; // el nombre lo pone armar-flujo.cjs
const r = $json;

const fecha = (s) => (s && s.length === 8 ? `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}` : s);
const paises = new Intl.DisplayNames(['es'], { type: 'region' });
const pais = (id) => { if (!id || id === '(not set)') return '(sin país)'; try { return paises.of(id) || id; } catch (e) { return id; } };

// Suma las filas que comparten la misma clave (evita claves repetidas al insertar).
function agrupar(filas, claves, sumas) {
  const m = new Map();
  for (const f of filas) {
    const k = claves.map((c) => f[c]).join('\u0001');
    const a = m.get(k);
    if (a) sumas.forEach((s) => { a[s] += f[s]; }); else m.set(k, { ...f });
  }
  return [...m.values()];
}

let filas = [];
if (t.fuente === 'ga4') {
  const dn = (r.dimensionHeaders || []).map((h) => h.name);
  const mn = (r.metricHeaders || []).map((h) => h.name);
  const regs = (r.rows || []).map((row) => {
    const o = {};
    dn.forEach((n, i) => { o[n] = row.dimensionValues[i].value; });
    mn.forEach((n, i) => { o[n] = Math.round(Number(row.metricValues[i].value) || 0); });
    return o;
  });
  const v = (x) => (x == null ? '' : String(x));
  if (t.tabla === 'ga4_canal_diario') {
    filas = agrupar(regs.map((o) => ({
      fecha: fecha(o.date), canal: v(o.sessionDefaultChannelGroup), fuente: v(o.sessionSource), medio: v(o.sessionMedium),
      campana: v(o.sessionCampaignName), contenido: v(o.sessionManualAdContent), termino: v(o.sessionManualTerm),
      visitas: o.sessions, conversiones: o.keyEvents,
    })), ['fecha', 'canal', 'fuente', 'medio', 'campana', 'contenido', 'termino'], ['visitas', 'conversiones']);
  } else if (t.tabla === 'ga4_evento_diario') {
    filas = agrupar(regs.map((o) => ({
      fecha: fecha(o.date), evento: v(o.eventName), origen: v(o['customEvent:origen']), correo: v(o['customEvent:correo']),
      eventos: o.eventCount, conversiones: o.keyEvents, personas: o.totalUsers,
    })), ['fecha', 'evento', 'origen', 'correo'], ['eventos', 'conversiones', 'personas']);
  } else if (t.tabla === 'ga4_pagina_diario') {
    filas = agrupar(regs.map((o) => ({ fecha: fecha(o.date), pagina: v(o.landingPage) || '(sin página)', visitas: o.sessions, conversiones: o.keyEvents })),
      ['fecha', 'pagina'], ['visitas', 'conversiones']);
  } else if (t.tabla === 'ga4_audiencia_diario') {
    filas = agrupar(regs.map((o) => ({ fecha: fecha(o.date), pais: pais(o.countryId), dispositivo: v(o.deviceCategory), visitas: o.sessions, conversiones: o.keyEvents })),
      ['fecha', 'pais', 'dispositivo'], ['visitas', 'conversiones']);
  }
} else if (t.fuente === 'meta') {
  // Una fila por día y campaña (time_increment=1). Las conversaciones son los chats de WhatsApp iniciados.
  const conversaciones = (acciones) => Math.round(Number(((acciones || []).find((a) => a.action_type === 'onsite_conversion.messaging_conversation_started_7d') || {}).value) || 0);
  filas = agrupar((r.data || []).map((x) => ({
    fecha: x.date_start, campana_id: String(x.campaign_id), campana: x.campaign_name || '', moneda: x.account_currency || 'COP',
    inversion: Number(x.spend) || 0, impresiones: Math.round(Number(x.impressions) || 0), clics: Math.round(Number(x.clicks) || 0),
    conversaciones: conversaciones(x.actions),
  })), ['fecha', 'campana_id'], ['inversion', 'impresiones', 'clics', 'conversaciones']);
} else if (t.fuente === 'brevo' && t.tabla === 'brevo_evento_diario') {
  // Mensajes distintos por día (hora de Bogotá), asunto y evento. Solo se guardan los días del tramo.
  const ev = r.events || [];
  if (ev.length >= t.limite) throw new Error(`Brevo devolvió ${ev.length} eventos entre ${t.desde} y ${t.hasta}: hay que partir el tramo`);
  const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });
  const m = new Map();
  for (const e of ev) {
    const f = dia.format(new Date(e.date));
    if (f < t.desde || f > t.hasta) continue;
    const k = [f, String(e.subject || '').trim(), e.event].join('\u0001');
    if (!m.has(k)) m.set(k, new Set());
    m.get(k).add(e.messageId || `${e.email}|${e.date}`);
  }
  filas = [...m.entries()].map(([k, ids]) => { const [f, asunto, evento] = k.split('\u0001'); return { fecha: f, asunto, evento, mensajes: ids.size }; });
} else if (t.fuente === 'brevo') {
  // Campañas masivas enviadas, con sus cifras acumuladas.
  const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });
  filas = (r.campaigns || []).filter((c) => c.sentDate).map((c) => {
    const s = (c.statistics && c.statistics.globalStats) || {};
    return { fecha: dia.format(new Date(c.sentDate)), campana_id: String(c.id), campana: c.name || '', asunto: c.subject || '',
      enviados: Math.round(s.sent || 0), entregados: Math.round(s.delivered || 0), aperturas: Math.round(s.uniqueViews || 0),
      clics: Math.round(s.uniqueClicks || 0), desuscritos: Math.round(s.unsubscriptions || 0),
      rebotes: Math.round((s.hardBounces || 0) + (s.softBounces || 0)) };
  });
} else {
  const campo = t.tabla === 'gsc_pagina_diario' ? 'pagina' : 'consulta';
  filas = agrupar((r.rows || []).map((x) => ({
    fecha: x.keys[0], sitio: t.sitio, [campo]: x.keys[1],
    clics: Math.round(x.clicks || 0), impresiones: Math.round(x.impressions || 0), pos_x_imp: (x.position || 0) * (x.impressions || 0),
  })), ['fecha', 'sitio', campo], ['clics', 'impresiones', 'pos_x_imp']);
}

return { json: { p_tabla: t.tabla, p_desde: t.desde, p_hasta: t.hasta, p_filas: filas, p_fuente: t.fuente, p_sitio: t.sitio } };

// Con la lista de campañas arma los pedidos: la analítica de hoy de cada campaña y las páginas de leads calientes.
const BASE = 'https://api.explee.com/public/api/v1/autogtm';
const campanas = $input.first().json.campaigns || [];
return [
  ...campanas.map((c) => ({ json: { tipo: 'analitica', campana_id: String(c.id), campana: c.name || '',
    url: `${BASE}/campaigns/${c.id}/analytics?period=today` } })),
  ...[0, 100, 200, 300, 400].map((offset) => ({ json: { tipo: 'leads', url: `${BASE}/hot-leads?limit=100&offset=${offset}` } })),
];

// Junta las respuestas: una fila por campaña con lo de hoy, y la lista completa de leads calientes.
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });
const pedidos = $('Pedidos Explee').all();
const respuestas = $input.all();
const num = (v) => (v == null || v === '' ? 0 : Number(v) || 0);

// Deja solo lo que escribió la persona: corta el correo citado ("El ... escribió:", "On ... wrote:", líneas con ">").
const propio = (texto) => {
  const lineas = String(texto || '').split(/\r?\n/);
  const fin = lineas.findIndex((l) => /^\s*>/.test(l) || /^\s*(El|On)\s.+(escribió|wrote):?\s*$/i.test(l) || /^\s*(El|On)\s.+\d{4}/.test(l));
  const t = (fin >= 0 ? lineas.slice(0, fin) : lineas).join(' ').replace(/\s+/g, ' ').trim();
  return t.length > 500 ? t.slice(0, 497) + '...' : t;
};

const nombres = {};
const diario = [];
const leads = new Map();
respuestas.forEach((r, i) => {
  const p = pedidos[i].json;
  if (p.tipo === 'analitica') {
    nombres[p.campana_id] = p.campana;
    const a = r.json;
    diario.push({ fecha: hoy, campana_id: p.campana_id, campana: p.campana, enviados: num(a.emails_sent), respuestas: num(a.total_replies),
      leads: num(a.hot_leads), gasto_usd: num(a.spend_usd) });
  } else {
    for (const l of r.json.leads || []) leads.set(String(l.id ?? `${l.email}|${l.company_domain}`), l);
  }
});

const filasLeads = [...leads.entries()].map(([id, l]) => ({
  fecha: l.became_hot_at ? dia.format(new Date(l.became_hot_at)) : null, lead_id: id,
  campana: nombres[l.campaign_id] || String(l.campaign_id || ''), empresa: l.company_name || '', dominio: l.company_domain || '',
  cargo: l.job_title || '', pais: l.country || '', motivo: propio(l.why_hot), nombre: l.name || '', correo: l.email || '',
  linkedin: l.linkedin_url || '', telefono: l.phone || '', nota: l.note || '',
}));

return [
  { json: { p_tabla: 'explee_campana_diario', p_desde: hoy, p_hasta: hoy, p_filas: diario, p_fuente: 'explee', p_sitio: null } },
  { json: { p_tabla: 'explee_lead', p_desde: hoy, p_hasta: hoy, p_filas: filasLeads, p_fuente: 'explee', p_sitio: null } },
];
